(async()=>{const F=m=>alert('Import impossible : '+m),k=location.pathname.match(/equipement\/(\d+)/);if(!k)return F("ouvrez d'abord la page d'un equipement DofusBook.");let j,b=[];try{const r=await fetch('/api/stuffs/dofus/public/'+k[1]);if(!r.ok)return F('DofusBook a repondu '+r.status+'. Si l equipement est prive, rendez-le public.');j=await r.json();const o=await fetch('/api/boosts/stuff/'+k[1]);if(o.ok)b=await o.json()}catch(e){return F('la requete a echoue ('+e+').')}const s=j.stuff,d={v:2,src:'dofusbook',stuff:{id:s.id,short_url:s.short_url,name:s.name,character_class:s.character_class,character_level:s.character_level,stuffItem:s.stuffItem,stuffCarac:s.stuffCarac},items_table:(j.items||[]).map(i=>({id:i.id,official:i.official})),fmItems:j.fmItems,fmGlobal:j.fmGlobal,fmWeapon:j.fmWeapon,fmStealWeapon:j.fmStealWeapon,boosts:b},t=TARGET+'#b='+encodeURIComponent(btoa(unescape(encodeURIComponent(JSON.stringify(d)))));const w=window.open(t,'_blank','noopener');if(!w)location.href=t})()
